class Team:
    def __init__(self, name, shares_status_openly, blames_after_failure, decides_without_manager):
        self.name = name
        self.shares_status_openly = shares_status_openly
        self.blames_after_failure = blames_after_failure
        self.decides_without_manager = decides_without_manager

    def culture_score(self) -> int:
        score = 0
        if self.shares_status_openly:
            score += 1
        if not self.blames_after_failure:
            score += 1
        if self.decides_without_manager:
            score += 1
        return score

    def is_agile_culture(self) -> bool:
        return self.culture_score() >= 2


teams = [
    Team("Payments", True, False, True),
    Team("Legacy Reports", False, True, False),
    Team("Onboarding", True, True, True),
]

for team in teams:
    label = "agile culture" if team.is_agile_culture() else "command-and-control"
    print(f"{team.name}: score={team.culture_score()} -> {label}")
